import requests
import sys
import io

# บังคับให้การแสดงผลรองรับ UTF-8
sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding='utf-8')
def request_otp(phone_number):
    # URL ที่เราแกะมาจาก APP_PROXY + Endpoint
    url = "https://www.supersports.co.th/apps/sso/api/sso/v2/sendOTP"
    
    # Headers สำคัญมาก เพื่อให้เซิร์ฟเวอร์เชื่อว่าเราส่งมาจากหน้าเว็บจริงๆ
    headers = {
        "Accept": "application/json",
        "Content-Type": "application/json",
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36",
        "Origin": "https://www.supersports.co.th",
        "Referer": "https://www.supersports.co.th/"
    }
    
    # ข้อมูลที่ส่งไป (ตามที่เห็นใน JS)
    payload = {
        "phoneNumber": phone_number,
        "countryCode": "th",
        "locale": "th",
        "platformType": "WEB"
    }

    try:
        response = requests.post(url, json=payload, headers=headers)
        
        # ตรวจสอบผลลัพธ์
        if response.status_code == 200:
            result = response.json()
            if result.get("success"):
                print(f"✅ ส่ง OTP ไปที่เบอร์ {phone_number} สำเร็จ!")
            elif result.get("isBlocked"):
                print(f"❌ โดนบล็อก! ต้องรออีก {result.get('blockRemainingMinutes')} นาที")
            else:
                print(f"⚠️ เซิร์ฟเวอร์ตอบกลับว่าไม่สำเร็จ: {result.get('message')}")
        else:
            print(f"🚫 เชื่อมต่อไม่ได้ (Status Code: {response.status_code})")
            
    except Exception as e:
        print(f"❗ เกิดข้อผิดพลาด: {e}")

# ทดสอบรัน (ใส่เบอร์ตัวเองเพื่อเช็ค)
request_otp("0641793150")